import React from 'react';
import { TrendingUp, Users, ShoppingCart } from 'lucide-react';

export default function App() {
  const stats = [
    { icon: Users, label: '总用户', value: '1,284', change: '+12.5%', color: 'rgb(252, 227, 238)' },
    { icon: ShoppingCart, label: '订单数', value: '856', change: '+8.2%', color: '#4CAF50' },
    { icon: TrendingUp, label: '增长率', value: '23.4%', change: '+5.1%', color: '#2196F3' }
  ];

  return (
    <div style={{ padding: '40px', background: '#f5f5f5', minHeight: '100vh' }}>
      <h2 style={{ marginBottom: '30px', color: '#333' }}>数据统计</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
        {stats.map((stat, index) => {
          const Icon = stat.icon;
          return (
            <div key={index} style={{
