import React, { useState } from 'react';
import { Layout, Menu, Breadcrumb, theme, Avatar, Dropdown, Button } from 'antd';
import { 
  DesktopOutlined, 
  PieChartOutlined, 
  FileOutlined, 
  TeamOutlined, 
  UserOutlined, 
  MenuUnfoldOutlined,
  MenuFoldOutlined
} from '@ant-design/icons';

const { Header, Content, Footer, Sider } = Layout;

function getItem(label, key, icon, children) {
  return {
    key,
    icon,
    children,
    label,
  };
}

const items = [
  getItem('仪表盘', '1', <PieChartOutlined />),
  getItem('工作台', '2', <DesktopOutlined />),
  getItem('用户管理', 'sub1', <UserOutlined />, [
    getItem('Tom', '3'),
    getItem('Bill', '4'),
    getItem('Alex', '5'),
  ]),
  getItem('团队', 'sub2', <TeamOutlined />, [
    getItem('Team 1', '6'),
    getItem('Team 2', '8'),
  ]),
  getItem('文件', '9', <FileOutlined />),
];

const App = () => {
  const [collapsed, setCollapsed] = useState(false);
  const {
    token: { colorBgContainer, borderRadiusLG },
  } = theme.useToken();

  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Sider collapsible collapsed={collapsed} onCollapse={(value) => setCollapsed(value)} style={{ background: '#001529' }}>
        <div style={{ height: 32, margin: 16, background: 'rgba(255, 255, 255, 0.2)', borderRadius: 6 }} />
        <Menu theme="dark" defaultSelectedKeys={['1']} mode="inline" items={items} />
      </Sider>
      <Layout>
        <Header style={{ padding: '0 16px', background: colorBgContainer, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Button
            type="text"
            icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            onClick={() => setCollapsed(!collapsed)}
            style={{
              fontSize: '16px',
              width: 64,
              height: 64,
            }}
          />
          <div style={{ marginRight: '16px' }}>
            <Avatar icon={<UserOutlined />} style={{ backgroundColor: 'rgb(252, 227, 238)' }} />
            <span style={{ marginLeft: '8px' }}>Admin</span>
          </div>
        </Header>
        <Content style={{ margin: '0 16px' }}>
          <Breadcrumb style={{ margin: '16px 0' }} items={[{ title: 'User' }, { title: 'Bill' }]} />
          <div
            style={{
              padding: 24,
              minHeight: 360,
              background: colorBgContainer,
              borderRadius: borderRadiusLG,
            }}
          >
            <h2>欢迎回来！</h2>
            <p>这是一个基于 Ant Design Layout 构建的标准后台管理系统布局。</p>
          </div>
        </Content>
        <Footer style={{ textAlign: 'center' }}>
          Ant Design Admin ©{new Date().getFullYear()} Created by Dom Agent
        </Footer>
      </Layout>
    </Layout>
  );
};

export default App;
